import{_ as s,C as i,o as a,c as n,j as t,a as d,E as r,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const b=JSON.parse('{"title":"Install with Docker Compose","description":"","frontmatter":{},"headers":[],"relativePath":"install/docker.md","filePath":"install/docker.md"}'),h={name:"install/docker.md"};function c(p,e,k,u,m,g){const o=i("Badge");return a(),n("div",null,[e[0]||(e[0]=t("h1",{id:"install-with-docker-compose",tabindex:"-1"},[d("Install with Docker Compose "),t("a",{class:"header-anchor",href:"#install-with-docker-compose","aria-label":'Permalink to "Install with Docker Compose"'},"​")],-1)),r(o,{type:"built",text:"Built"}),e[1]||(e[1]=l(` One machine, to try and test Octryx AI. With the demo it is the <a href="/docs/start/first-run">First run</a>; for development with hot reload, see <a href="/docs/contribute/dev-setup">Development setup</a>.<h2 id="you-need" tabindex="-1">You need <a class="header-anchor" href="#you-need" aria-label="Permalink to &quot;You need&quot;">​</a></h2><ul><li>Docker Desktop, Rancher Desktop or Podman with <code>docker compose</code> 2.23 or newer (<code>docker compose version</code>). Give the container engine 8 GB RAM and 20 GB disk.</li><li>Internet access (base images, PyPI, npm, the model, the demo repository on GitHub).</li><li>Exactly one model access for the platform: <ul><li>an Anthropic API key (simplest; <a href="https://console.anthropic.com" target="_blank" rel="noreferrer">https://console.anthropic.com</a>). Octryx AI reaches it through Anthropic&#39;s OpenAI-compatible endpoint;</li><li>or any OpenAI-compatible endpoint with a key: OpenAI, Azure OpenAI, a LiteLLM gateway, vLLM, LM Studio or Ollama;</li><li>or AWS Bedrock with <code>bedrock:InvokeModel</code> in a region where the model is enabled;</li><li>or an OpenRouter key.</li></ul></li><li>Coding runs on a developer&#39;s machine can also use the person&#39;s own Claude subscription through the <a href="/docs/install/launcher">launcher</a>; that needs no platform key.</li><li>Chrome, Edge or Firefox.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p>Get the code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/octryx-ai/octryx.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> octryx</span></span></code></pre></div></li><li><p>Configure one model:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>Open <code>.env</code> and fill in <strong>one</strong> block; leave the others commented out. <code>LLM_PROVIDER</code> takes <code>anthropic</code>, <code>openai</code>, <code>bedrock</code> or <code>openrouter</code>; any other provider is added later under <strong>Admin › Models › Providers</strong>. With an Anthropic key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LLM_PROVIDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AGENT_DEFAULT_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">claude-sonnet-5-5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LLM_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-ant-…</span></span></code></pre></div><p>For an OpenAI-compatible endpoint: <code>LLM_PROVIDER=openai</code>, <code>LLM_ENDPOINT_URL</code>, <code>AGENT_DEFAULT_MODEL</code>, <code>LLM_API_KEY</code>. For Bedrock: <code>LLM_PROVIDER=bedrock</code>, <code>AGENT_DEFAULT_MODEL</code> (a model id enabled in your region), <code>AWS_REGION</code> and the AWS keys. For OpenRouter: <code>LLM_PROVIDER=openrouter</code> and <code>LLM_API_KEY</code>. Any other value creates no model access; the start log then says <code>startup.llm_provider_unsupported</code> and names the valid values. With AWS SSO you can append the keys with <code>aws configure export-credentials --profile &lt;profile&gt; --format env-no-export &gt;&gt; .env</code>.</p></li><li><p>Start. The first build takes 10–20 minutes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><ul><li><p>With demo content, add the demo file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.demo.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>(or <code>COMPOSE_FILE=docker-compose.yml:docker-compose.demo.yml</code> in <code>.env</code>). This creates the Workspace &quot;Demo Shop&quot;:</p><ul><li>a small sample shop in the repository <code>demo/demo-shop</code> on a local stand-in for GitHub at <code>http://127.0.0.1:8434</code>, on this machine only (clone it with <code>git clone http://127.0.0.1:8434/demo/demo-shop.git</code>);</li><li>its README and docs as Knowledge;</li><li>the connection &quot;GitHub (demo)&quot; and the PR review bot (status <strong>inform</strong>);</li><li>the work items OCX-1 (a bug) and OCX-2 (a story);</li><li>a <strong>Sample run</strong> in <strong>Work › Runs</strong>: a real Story / epic delivery run of OCX-2, recorded on another install, with its pull request and the bot&#39;s review on the local GitHub.</li></ul><p>No Jira, GitHub or other credential is needed beyond the model access in <code>.env</code>. The demo is ready when <code>docker compose -f docker-compose.yml -f docker-compose.demo.yml logs demo</code> ends with &quot;demo: ready in the Workspace &#39;Demo Shop&#39;&quot;. The same two files with <code>down -v</code> remove it again, with all volumes. <code>docker-compose.yml</code> on its own starts no demo and opens no demo port.</p></li><li><p>With Podman instead of Docker, first run <code>export DOCKER_HOST=unix://$(podman machine inspect --format &#39;{{.ConnectionInfo.PodmanSocket.Path}}&#39;)</code>.</p></li></ul></li><li><p>Sign in for the first time. There is no default password: a one-time setup code creates the admin.</p><p>Get the one-time setup code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;setup code&quot;</span></span></code></pre></div><p>The line names the setup page, <code>http://localhost:8000/chat/setup</code> (or your <code>OCTRYX_PORT</code>).</p></li><li><p>Open that page. Enter the setup code, your name, e-mail and a password of at least 12 characters. From then on, you sign in with the username <strong>admin</strong>. The <strong>Setup guide</strong> opens and shows what is still missing.</p></li></ol><h2 id="is-it-running" tabindex="-1">Is it running? <a class="header-anchor" href="#is-it-running" aria-label="Permalink to &quot;Is it running?&quot;">​</a></h2><ul><li><code>docker compose ps</code>: <code>api</code> is <code>healthy</code>; <code>migrate</code> and <code>secrets-init</code> exited with 0.</li><li><code>curl http://localhost:8000/api/v1/health</code> returns <code>{&quot;status&quot;:&quot;ok&quot;}</code>.</li><li>In the chat, ask &quot;Reply only with pong&quot;. The answer is &quot;pong&quot;.</li><li>Demo only: choose the Workspace with the top icon in the left bar (above &quot;Chat&quot;), then &quot;Demo Shop&quot;. Knowledge › Search for &quot;rollback&quot; finds the incident runbook.</li></ul><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message or sign</th><th>Cause and fix</th></tr></thead><tbody><tr><td><code>required variable LLM_PROVIDER is missing</code></td><td><code>.env</code> is missing or no block is filled in (step 2).</td></tr><tr><td><code>port is already allocated</code></td><td>Port 8000 is taken. Set <code>OCTRYX_PORT=8080</code> in <code>.env</code> and open <code>http://localhost:8080/chat/setup</code>.</td></tr><tr><td>No &quot;setup code&quot; in the log</td><td>The api is still starting. Watch <code>docker compose logs -f api</code>.</td></tr><tr><td>Search says &quot;Choose a workspace&quot;</td><td>Click the Workspace icon at the top of the left bar and choose a Workspace.</td></tr><tr><td>Sign-in returns to the login page without an error</td><td>The browser drops the Secure cookies on plain http. Use Chrome, Edge or Firefox and <code>localhost</code>, not the IP address.</td></tr><tr><td>Chat: <code>authentication_error</code> or <code>invalid api key</code></td><td>The endpoint&#39;s key is wrong or revoked. Fix it under Admin › Models (see the last row).</td></tr><tr><td>Chat: <code>UnrecognizedClient</code>, <code>ExpiredToken</code>, <code>AccessDenied</code> (Bedrock)</td><td>The AWS keys are wrong or expired (SSO exports often last only hours). Export them again, then <code>docker compose up -d</code>.</td></tr><tr><td>Chat: model not found</td><td>The model is not available to your key or in your region. Change <code>AGENT_DEFAULT_MODEL</code> (or <code>AWS_REGION</code>).</td></tr><tr><td>Setup guide: &quot;has no price – costs are not counted&quot;</td><td>There is no list price for this model. This is only a notice. Enter the price under <strong>Admin › Models › Catalog</strong> (column <strong>Price / 1M (in · out)</strong>) and costs are counted too.</td></tr><tr><td>Model access changed after the first start, without effect</td><td><code>.env</code> is read on the first start only. After that, change the access under Admin › Models.</td></tr></tbody></table><p>Start over: <code>docker compose down -v</code>. This deletes <strong>everything</strong>: database, documents and the generated keys.</p><p>For development with hot reload, see <a href="/docs/contribute/dev-setup">Development setup</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/install/launcher">Connect your machine with octryx-claude</a></li><li><a href="/docs/install/metrics">Metrics for Prometheus and Grafana</a></li></ul>`,17))])}const F=s(h,[["render",c]]);export{b as __pageData,F as default};
